import re

__all__ = ["best_match"]

# ---------------------------------------------------------------------------
# Grammar (ASCII only; explicit classes instead of \d, which matches Unicode)
# ---------------------------------------------------------------------------
_NUM = r"(?:0|[1-9][0-9]*)"
_PRE_ID = r"(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
_PRE = rf"{_PRE_ID}(?:\.{_PRE_ID})*"
_BUILD = r"[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*"

_VERSION_RE = re.compile(
    rf"({_NUM})\.({_NUM})\.({_NUM})(?:-({_PRE}))?(?:\+({_BUILD}))?"
)
_FULL_PATTERN_RE = re.compile(rf"({_NUM})\.({_NUM})\.({_NUM})(?:-({_PRE}))?")
_NUM_RE = re.compile(_NUM)
_WILDCARDS = {"x", "X", "*"}
_OPERATORS = ("<=", ">=", "<", ">", "=", "^", "~")  # longest first

# ---------------------------------------------------------------------------
# Numbers are kept as canonical decimal strings (no leading zeros), so they
# can be arbitrarily large without running into int/str conversion limits.
# ---------------------------------------------------------------------------


def _num_key(s):
    return (len(s), s)


def _inc(s):
    digits = list(s)
    i = len(digits) - 1
    while i >= 0 and digits[i] == "9":
        digits[i] = "0"
        i -= 1
    if i < 0:
        return "1" + "".join(digits)
    digits[i] = chr(ord(digits[i]) + 1)
    return "".join(digits)


def _is_numeric_id(s):
    return all("0" <= c <= "9" for c in s)


def _id_key(s):
    if _is_numeric_id(s):
        return (0, len(s), s)
    return (1, 0, s)  # ASCII order == code point order for ASCII strings


def _key(major, minor, patch, pre):
    """Precedence key. `pre` is None or a tuple of identifier strings."""
    base = (_num_key(major), _num_key(minor), _num_key(patch))
    if pre is None:
        return base + (1, ())
    return base + (0, tuple(_id_key(i) for i in pre))


_LOWEST_PRE = ("0",)  # "-0": the lowest possible pre-release


def _parse_version(s):
    """Return (key, (major, minor, patch), pre) or None if not a valid version."""
    if not isinstance(s, str):
        return None
    m = _VERSION_RE.fullmatch(s)
    if m is None:
        return None
    major, minor, patch, pre, _build = m.groups()
    pre_t = tuple(pre.split(".")) if pre is not None else None
    return _key(major, minor, patch, pre_t), (major, minor, patch), pre_t


# ---------------------------------------------------------------------------
# Range parsing
# ---------------------------------------------------------------------------


def _parse_pattern(p):
    """Return (numbers, pre, is_full).

    numbers: list of written numbers (strings) before the first wildcard.
    pre: tuple of identifiers or None (only possible for full versions).
    """
    m = _FULL_PATTERN_RE.fullmatch(p)
    if m is not None:
        major, minor, patch, pre = m.groups()
        pre_t = tuple(pre.split(".")) if pre is not None else None
        return [major, minor, patch], pre_t, True

    parts = p.split(".")
    if not 1 <= len(parts) <= 3:
        raise ValueError(f"invalid pattern: {p!r}")
    numbers = []
    seen_wildcard = False
    for part in parts:
        if part in _WILDCARDS:
            seen_wildcard = True
        elif _NUM_RE.fullmatch(part):
            if seen_wildcard:
                raise ValueError(f"invalid pattern: {p!r}")
            numbers.append(part)
        else:
            raise ValueError(f"invalid pattern: {p!r}")
    if len(numbers) == 3:  # would have matched the full regex
        raise ValueError(f"invalid pattern: {p!r}")
    return numbers, None, False


def _incremented(nums, i):
    """Pad `nums` to 3 numbers, increment position i, zero the rest."""
    padded = list(nums) + ["0"] * (3 - len(nums))
    out = padded[:i] + [_inc(padded[i])] + ["0"] * (2 - i)
    return tuple(out)


def _caret_index(nums):
    for i, n in enumerate(nums):
        if n != "0":
            return i
    return len(nums) - 1


def _parse_comparator(token):
    """Return (constraints, prerelease_triple_or_None).

    constraints: list of (op, key) with op in {'eq','gt','ge','lt','le'}.
    """
    op = ""
    for candidate in _OPERATORS:
        if token.startswith(candidate):
            op = candidate
            break
    pattern = token[len(op):]
    if not pattern:
        raise ValueError(f"invalid comparator: {token!r}")

    nums, pre, full = _parse_pattern(pattern)

    if not nums:
        if op:
            raise ValueError(f"operator not allowed before {pattern!r}")
        return [], None

    def lower_bound_key(ns):
        padded = list(ns) + ["0"] * (3 - len(ns))
        return _key(padded[0], padded[1], padded[2], None)

    def minus0(triple):
        return _key(triple[0], triple[1], triple[2], _LOWEST_PRE)

    if full:
        major, minor, patch = nums
        vkey = _key(major, minor, patch, pre)
        pre_triple = (major, minor, patch) if pre is not None else None
        if op in ("", "="):
            cons = [("eq", vkey)]
        elif op == ">":
            cons = [("gt", vkey)]
        elif op == ">=":
            cons = [("ge", vkey)]
        elif op == "<":
            cons = [("lt", vkey)]
        elif op == "<=":
            cons = [("le", vkey)]
        elif op == "~":
            cons = [("ge", vkey), ("lt", minus0(_incremented(nums, 1)))]
        else:  # "^"
            cons = [("ge", vkey), ("lt", minus0(_incremented(nums, _caret_index(nums))))]
        return cons, pre_triple

    # Partial version: 1 or 2 written numbers.
    last = len(nums) - 1
    low = lower_bound_key(nums)
    next_up = _incremented(nums, last)
    if op in ("", "=", "~"):
        cons = [("ge", low), ("lt", minus0(next_up))]
    elif op == ">":
        cons = [("ge", _key(next_up[0], next_up[1], next_up[2], None))]
    elif op == ">=":
        cons = [("ge", low)]
    elif op == "<":
        padded = list(nums) + ["0"] * (3 - len(nums))
        cons = [("lt", minus0(tuple(padded)))]
    elif op == "<=":
        cons = [("lt", minus0(next_up))]
    else:  # "^"
        cons = [("ge", low), ("lt", minus0(_incremented(nums, _caret_index(nums))))]
    return cons, None


def _parse_range(range_expr):
    if not isinstance(range_expr, str):
        raise ValueError("range must be a string")
    expr = range_expr.strip(" ")
    if not expr:
        raise ValueError("empty range")
    alternatives = []
    for alt in expr.split("||"):
        alt = alt.strip(" ")
        if not alt:
            raise ValueError("empty alternative in range")
        constraints = []
        pre_triples = set()
        for token in alt.split(" "):
            if token == "":
                continue  # multiple spaces between comparators
            cons, pre_triple = _parse_comparator(token)
            constraints.extend(cons)
            if pre_triple is not None:
                pre_triples.add(pre_triple)
        alternatives.append((constraints, pre_triples))
    return alternatives


# ---------------------------------------------------------------------------
# Matching
# ---------------------------------------------------------------------------


def _check(op, vkey, bound):
    if op == "eq":
        return vkey == bound
    if op == "gt":
        return vkey > bound
    if op == "ge":
        return vkey >= bound
    if op == "lt":
        return vkey < bound
    return vkey <= bound  # "le"


def _satisfies(parsed, alternatives):
    vkey, triple, pre = parsed
    for constraints, pre_triples in alternatives:
        if not all(_check(op, vkey, bound) for op, bound in constraints):
            continue
        if pre is not None and triple not in pre_triples:
            continue
        return True
    return False


def best_match(versions: list[str], range_expr: str) -> str | None:
    alternatives = _parse_range(range_expr)  # raises ValueError even if versions is empty
    best = None
    best_key = None
    for v in versions:
        parsed = _parse_version(v)
        if parsed is None:
            continue
        if not _satisfies(parsed, alternatives):
            continue
        if best_key is None or parsed[0] > best_key:  # strict: first wins on ties
            best, best_key = v, parsed[0]
    return best
